-- RESPONSABLES: todos los empleados activos del departamento participan
INSERT INTO responsables_objetivos (id_asignacion, id_empleado, fecha_asignacion)
SELECT a.id_asignacion, e.id_empleado, a.fecha_asignacion
FROM objetivos_departamento a
JOIN empleados e ON e.id_departamento = a.id_departamento AND e.activo = true
WHERE e.cif IN ('EMP-001', 'EMP-002', 'EMP-003', 'EMP-004', 'EMP-005', 'EMP-006', 'EMP-007', 'EMP-008', 'EMP-009')
ON CONFLICT DO NOTHING;

-- SEGUIMIENTOS DEPARTAMENTALES (registrados por el jefe del departamento)
INSERT INTO seguimientos (id_asignacion, id_empleado, id_departamento, fecha_seguimiento, tipo, porcentaje_avance, observaciones, registrado_por)
SELECT (SELECT a.id_asignacion FROM objetivos_departamento a JOIN objetivos o ON o.id_objetivo = a.id_objetivo JOIN departamentos d ON d.id_departamento = a.id_departamento JOIN periodos_evaluacion p ON p.id_periodo = a.id_periodo WHERE o.nombre = 'Mantener al día los estados de cuenta' AND d.nombre = 'Cartera y Cobro' AND p.nombre = 'Primer semestre 2026'), NULL, (SELECT id_departamento FROM departamentos WHERE nombre = 'Cartera y Cobro'), DATE '2026-03-31', 'DEPARTAMENTAL', 45, 'Primer corte del semestre.', (SELECT id_empleado FROM empleados WHERE cif = 'EMP-001')
WHERE NOT EXISTS (SELECT 1 FROM seguimientos WHERE id_asignacion = (SELECT a.id_asignacion FROM objetivos_departamento a JOIN objetivos o ON o.id_objetivo = a.id_objetivo JOIN departamentos d ON d.id_departamento = a.id_departamento JOIN periodos_evaluacion p ON p.id_periodo = a.id_periodo WHERE o.nombre = 'Mantener al día los estados de cuenta' AND d.nombre = 'Cartera y Cobro' AND p.nombre = 'Primer semestre 2026') AND tipo = 'DEPARTAMENTAL' AND fecha_seguimiento = DATE '2026-03-31');
