WHERE NOT EXISTS (SELECT 1 FROM seguimientos WHERE id_asignacion = (SELECT a.id_asignacion FROM objetivos_departamento a JOIN objetivos o ON o.id_objetivo = a.id_objetivo JOIN departamentos d ON d.id_departamento = a.id_departamento JOIN periodos_evaluacion p ON p.id_periodo = a.id_periodo WHERE o.nombre = 'Mantener al día los estados de cuenta' AND d.nombre = 'Cartera y Cobro' AND p.nombre = 'Primer semestre 2026') AND tipo = 'DEPARTAMENTAL' AND fecha_seguimiento = DATE '2026-06-25');
